export const istDay=(d=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
export const addDay=(date:string,n:number)=>new Date(Date.parse(date+'T12:00:00Z')+n*86400000).toISOString().slice(0,10);
const niceDay=(d:string)=>new Date(d+'T12:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
const genderLabel=(s:string)=>s.charAt(0)+s.slice(1).toLowerCase();
const docLanguages=(d:ProviderItem)=>d.languagesList||[];
const nextStamp=(d:ProviderItem)=>d.nextAvailable?Date.parse(`${d.nextAvailable.date}T${d.nextAvailable.time.slice(0,5)}:00+05:30`):Infinity;
function DoctorIdentity({doctor:d,large=false}:{doctor:ProviderItem;large?:boolean}){return <div className={'dj-identity '+(large?'large':'')}><div className="dj-avatar"><MediaImage src={d.logo} name={d.name} kind="doctor" gender={d.gender}/></div><div><h2>{d.name}{d.registrationVerified&&<ShieldCheck aria-label="Registration verified"/>}</h2>{d.qualification&&<p>{d.qualification}</p>}{d.designation&&<p>{d.designation}</p>}{(d.specialization||d.specialtyOrType)&&<p>{d.specialization||d.specialtyOrType}{d.experienceYears!=null&&d.experienceYears>0?` · ${d.experienceYears} years experience`:''}</p>}{d.rating&&d.rating.count>0&&<p className="dj-rating">★ {d.rating.average.toFixed(1)} <span>({d.rating.count} reviews)</span></p>}{!!d.expertise?.length&&<div className="dj-expertise">{d.expertise.map(x=><span key={x}>{x}</span>)}</div>}{large&&d.medicalRegistrationNumber&&<p>Registration: {d.medicalRegistrationNumber}{d.medicalCouncilName?` · ${d.medicalCouncilName}`:''}</p>}</div></div>;}
function Fees({doctor:d,home}:{doctor:ProviderItem;home?:HomeVisitDoctor}){return <dl className="dj-fees">{d.inClinicFee!=null&&<div><dt><Building2/>In-clinic</dt><dd>{rupees(d.inClinicFee)}</dd></div>}{d.videoFee!=null&&<div><dt><Video/>Video</dt><dd>{rupees(d.videoFee)}</dd></div>}{home&&<div><dt><House/>Home visit</dt><dd>{rupees(home.fee)}</dd></div>}</dl>;}

