 const open=(selection?:{date:string;slot:number;clinic:number})=>{const next=new URLSearchParams(props.params);next.set('book','1');if(selection){next.set('date',selection.date);next.set('slot',String(selection.slot));next.set('clinic',String(selection.clinic));}else{next.delete('date');next.delete('slot');next.delete('clinic');}navigate({search:next.toString()});};
 if(props.booking)return <DoctorProfileV2 {...props} onBook={()=>open()}/>;
 return <div className="dj-profile-inline-shell"><DoctorProfileV2 {...props} onBook={()=>open()}/><DoctorInlineBooking doctor={props.doctor} onContinue={open} onFullCalendar={()=>open()}/></div>;
